select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, ServiceName as service, min(Value) as up
from otel.metrics_gauge where MetricName = 'up' and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
group by all order by 1

select Timestamp as time, ServiceName as service, SeverityText as severity, Body as message, TraceId as trace
from otel.logs where SeverityNumber >= 13 and Timestamp >= epoch_ms(${__from}) and Timestamp < epoch_ms(${__to})
order by Timestamp desc limit 500

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, 'used' as space, max(Value) as bytes
from otel.metrics_gauge where MetricName = 'juicefs_used_space' and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
group by all order by 1

with points as (
select TimeUnix, ResourceAttributes['service.instance.id'] as replica, Attributes['start'] as start, Sum, Count from otel.metrics_histogram
where MetricName = 'neon_control_wake_duration_seconds' and TimeUnix >= epoch_ms(${__from}) - interval 10 minute and TimeUnix < epoch_ms(${__to})
), wakes as (
select TimeUnix, start, greatest(Sum - lag(Sum) over replicas, 0) as seconds, greatest(Count - lag(Count) over replicas, 0) as wakes
from points window replicas as (partition by replica, start order by TimeUnix)
)
select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, start, sum(seconds) / sum(wakes) as seconds
from wakes where wakes > 0 and TimeUnix >= epoch_ms(${__from})
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, Attributes['compute'] as compute, max(Value) as replicas
from otel.metrics_gauge where MetricName = 'neon_control_compute_replicas' and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, Attributes['compute'] as compute, max(Value) as bytes
from otel.metrics_gauge where MetricName = 'neon_control_replica_lag_bytes' and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, Attributes['alasio.sandbox.release.outcome'] as outcome, sum(added) as releases
from (
select TimeUnix, Attributes, Value - coalesce(lag(Value) over series, 0) as added
from otel.metrics_sum where MetricName = 'alasio.sandbox.releases' and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added > 0
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, if(Attributes['alasio.sandbox.restore.outcome'] = 'fallback', 'fell back: ' || Attributes['alasio.sandbox.restore.fallback'], Attributes['alasio.sandbox.restore.outcome']) as outcome, sum(added) as restores
from (
select TimeUnix, Attributes, Value - coalesce(lag(Value) over series, 0) as added
from otel.metrics_sum where MetricName = 'alasio.sandbox.restores' and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added > 0
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, 'restore' as duration, sum(added_sum) / sum(added_count) as seconds
from (
select TimeUnix, MetricName, Sum - coalesce(lag(Sum) over series, 0) as added_sum, Count::bigint - coalesce(lag(Count::bigint) over series, 0) as added_count
from otel.metrics_histogram where MetricName in ('alasio.sandbox.restore.duration') and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by MetricName, ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added_count > 0
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, if(MetricName = 'alasio.node_agent.checkpoint.pause', 'paused', 'uploading') as phase, sum(added_sum) / sum(added_count) as seconds
from (
select TimeUnix, MetricName, Sum - coalesce(lag(Sum) over series, 0) as added_sum, Count::bigint - coalesce(lag(Count::bigint) over series, 0) as added_count
from otel.metrics_histogram where MetricName in ('alasio.node_agent.checkpoint.pause', 'alasio.node_agent.checkpoint.upload') and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by MetricName, ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added_count > 0
group by all order by 1

select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, 'image' as image, sum(added_sum) / sum(added_count) as bytes
from (
select TimeUnix, MetricName, Sum - coalesce(lag(Sum) over series, 0) as added_sum, Count::bigint - coalesce(lag(Count::bigint) over series, 0) as added_count
from otel.metrics_histogram where MetricName in ('alasio.node_agent.snapshot.size') and TimeUnix >= epoch_ms(${__from}) - interval 1 hour and TimeUnix < epoch_ms(${__to})
window series as (partition by MetricName, ResourceAttributes, Attributes, StartTimeUnix order by TimeUnix)
) where TimeUnix >= epoch_ms(${__from}) and added_count > 0
group by all order by 1

select time, held, if(held = 'gVisor releases kept', max(value), sum(value)) as count
from (
select time_bucket(to_milliseconds(${__interval_ms}), TimeUnix) as time, ResourceAttributes,
if(MetricName = 'alasio.node_agent.releases', 'gVisor releases kept', 'snapshots cached of ' || Attributes['alasio.gvisor.release']) as held, arg_max(Value, TimeUnix) as value
from otel.metrics_gauge where MetricName in ('alasio.node_agent.releases', 'alasio.node_agent.cache.snapshots') and TimeUnix >= epoch_ms(${__from}) and TimeUnix < epoch_ms(${__to})
group by all
) group by time, held order by 1
